/// Spawn the surface's PTY *without* waiting for window mount (issue #67, background run). Normally
/// `createSurface` fires from `viewDidMoveToWindow`, so a run tab that's started in the background and
/// never made active would never mount — and its command would never start (the toast would claim
/// "running" while nothing ran). `createSurface` only hard-requires positive bounds
/// (`backingPixelSize`); every window reference inside it is a soft fallback. So give the view a
/// non-zero frame and create the surface now; it re-sizes correctly when it later mounts into a real
/// pane. No-op if the surface already exists or this is a test view (`spawnsSurface == false`).
func ensureSurfaceCreated(initialSize: CGSize) {
  guard spawnsSurface, surface == nil else { return }
  if bounds.width <= 0 || bounds.height <= 0 {
    // Positive bounds are the one thing `createSurface` can't proceed without (it defers via
    // `pendingSurfaceCreation` otherwise). A sane initial size also gives the spawned command a
    // reasonable COLUMNS/LINES until the first on-window resize.
    let size =
      (initialSize.width > 0 && initialSize.height > 0)
      ? initialSize : CGSize(width: 800, height: 480)
    setFrameSize(size)
  }
  createSurface()
}

private func destroySurface() {
  if let surface { ghostty_surface_free(surface) }
  surface = nil
  lastSetFocus = nil  // a new surface starts unfocused — don't let a stale value skip the re-sync
  freeSurfaceCStrings()
}

/// Explicit teardown on close/delete (plan A1). Clears callbacks first so a late libghostty
/// callback resolving this view via `userdata` can't invoke a dangling closure, then frees.
func tearDown() {
  isTornDown = true  // dead view: block any later re-spawn (issue #7 phantom respawn)
  setHandCursor(false)
  onActivity = nil
  onOpenURL = nil
  onCmdClickFile = nil
  resolveCmdHoverFile = nil
  onFocused = nil
  onChildExited = nil
  onCloseRequested = nil
  progressActive = false
  progressTimeoutTimer?.invalidate()
  progressTimeoutTimer = nil
  stopAccessibilityPolling()
  if let occlusionObserver {
    NotificationCenter.default.removeObserver(occlusionObserver)
    self.occlusionObserver = nil
  }
  for observer in keyWindowObservers { NotificationCenter.default.removeObserver(observer) }
  keyWindowObservers = []
  destroySurface()
  removeFromSuperview()
}

deinit {
  progressTimeoutTimer?.invalidate()
  accessibilityPollTimer?.invalidate()
  if let occlusionObserver { NotificationCenter.default.removeObserver(occlusionObserver) }
  for observer in keyWindowObservers { NotificationCenter.default.removeObserver(observer) }
  if let surface { ghostty_surface_free(surface) }
  freeSurfaceCStrings()
}

private func freeSurfaceCStrings() {
  for ptr in surfaceCStrings { free(ptr) }
  surfaceCStrings.removeAll()
  envVarsBuffer?.deinitialize(count: envVarCount)
  envVarsBuffer?.deallocate()
  envVarsBuffer = nil
  envVarCount = 0
}

/// Configure libghostty to spawn `workroom-session attach` for a background session.
@discardableResult
private func applyPersistentSession(
  to config: inout ghostty_surface_config_s,
  environment: inout [(String, String)]
) -> Bool {
  // No session was requested for this pane — not a failure, nothing to log.
  guard let persistentSessionID else { return false }
  guard
    PersistentSessionService.shared.isAvailable,
    let attach = PersistentSessionService.shared.attachCommand(),
    let attachPointer = strdup(attach)
